  it('wraps a non-Error rejection in an Error with cause and rethrows the original value', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createErrorProvider('raw failure'), promptBuilder, undefined, {
      hooks,
    });
    const rejected = await orchestrator
      .processMessage(createSession('hello'))
      .then(() => 'resolved')
      .catch((reason: unknown) => reason);

    expect({rejected, isError: receivedError instanceof Error, cause: receivedError?.cause}).toEqual({
      rejected: 'raw failure',
      isError: true,
      cause: 'raw failure',
    });
  });
});

